// === Tab: mySketch ===
let theShader;
let shaderTexture;

let theta = 0;
let cubeSize;
let rotationSpeed = 0.002;

function preload(){
  // Load the shader
  theShader = loadShader('https://openprocessing.org/sketch/2342671/files/vert.vert', 'noisyFrag.frag');
}

function setup() {
  // Shaders require WEBGL mode to work
  createCanvas(4/3*windowHeight, windowHeight, WEBGL);
  stroke(0);

  // Initialize the createGraphics layer
  shaderTexture = createGraphics(width, height, WEBGL);
  shaderTexture.stroke(0);
  cubeSize = max(width, height) * 0.2;
	stroke(255);
  rectMode(CENTER);
}

function draw() {
  // Set the active shader on the createGraphics layer
  background(255);
  shaderTexture.shader(theShader);

  // Send uniform values to the shader
  theShader.setUniform("u_resolution", [width, height]);
  theShader.setUniform("u_time", millis() / 1000.0);
  theShader.setUniform("mouse", [(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, height, height, 0)]);

  // Render geometry on the shaderTexture layer
  shaderTexture.rect(0, 0, width, height);

  // Pass the shader as a texture
  texture(shaderTexture);

  // Draw the rotating cube
  push();    
  translate(0, 0, 0);
  rotateZ(theta);
  rotateX(theta);
  rotateY(theta);  
  box(min(height, width) * 0.5);
  pop();

  // Update the rotation angle
  theta += rotationSpeed;
}

function keyPressed() {
  if (key === 's' || key === 'S') {
    saveCanvas('i', 'jpg');
  } else if (key === 'ArrowUp') {
    rotationSpeed += 0.001;
  } else if (key === 'ArrowDown') {
    rotationSpeed = max(0, rotationSpeed - 0.001);
  }
}

